import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8794/tests/alunix-r8/runs/V3d/index.html"

async def goto(pg):
    for attempt in range(8):
        try:
            await pg.goto(URL, wait_until="load", timeout=15000)
            return
        except Exception:
            if attempt == 7: raise

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        pg = await browser.new_page(viewport={"width":1440,"height":900})
        await goto(pg)
        await pg.wait_for_timeout(500)

        # 1. Giant top vs scrollY bisection
        print("=== Giant top position ===")
        for y in range(3900, 4700, 50):
            await pg.evaluate(f"window.scrollTo(0,{y})")
            await pg.wait_for_timeout(80)
            data = await pg.evaluate('''() => {
              const g = document.querySelector('.panel-giant');
              const r = g.getBoundingClientRect();
              const cs = getComputedStyle(document.querySelector('#giant-section'));
              const h1 = document.querySelector('.giant');
              const h1r = h1.getBoundingClientRect();
              return {top: Math.round(r.top), h1Bottom: Math.round(h1r.bottom), width: Math.round(r.width)};
            }''')
            scps = await pg.evaluate("getComputedStyle(document.querySelector('#giant-section')).getPropertyValue('--sc-ps')")
            print(y, data, "sc-ps=", scps)

        await browser.close()

asyncio.run(main())

