import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8794/tests/alunix-r8/runs/V3d/index.html"

async def goto(pg):
    for attempt in range(8):
        try:
            await pg.goto(URL, wait_until="load", timeout=15000)
            return
        except Exception:
            if attempt == 7: raise

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        pg = await browser.new_page(viewport={"width":1440,"height":900})
        await goto(pg)
        await pg.wait_for_timeout(500)
        for y in range(3200, 4400, 50):
            await pg.evaluate(f"window.scrollTo(0,{y})")
            await pg.wait_for_timeout(80)
            data = await pg.evaluate('''() => {
              const fig = document.querySelector('.thesis-figure');
              const calyx = document.querySelector('.calyx-fig');
              const panel = document.querySelector('.panel-giant');
              const h1 = document.querySelector('.giant');
              const r = fig.getBoundingClientRect();
              const c = calyx.getBoundingClientRect();
              const rp = panel.getBoundingClientRect();
              const g = h1.getBoundingClientRect();
              function vis(rect){return rect.bottom>0 && rect.top<900 && rect.right>0 && rect.left<1440;}
              const overlapX = Math.max(0, Math.min(r.right,g.right) - Math.max(r.left,g.left));
              const overlapY = Math.max(0, Math.min(r.bottom,g.bottom) - Math.max(r.top,g.top));
              return {
                thesisVis: vis(r), calyxVis: vis(c), h1Vis: vis(g),
                widthPct: Math.round(1000*rp.width/1440)/10,
                collide: overlapX>0 && overlapY>0 && vis(r) && vis(g)
              };
            }''')
            print(y, data)
        await browser.close()

asyncio.run(main())

