import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8794/tests/alunix-r8/runs/V3d/index.html"

async def goto(pg):
    for attempt in range(8):
        try:
            await pg.goto(URL, wait_until="load", timeout=15000)
            return
        except Exception:
            if attempt == 7: raise

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        pg = await browser.new_page(viewport={"width":1440,"height":900})
        await goto(pg)
        await pg.wait_for_timeout(500)
        data = await pg.evaluate('''() => {
          const ch = document.querySelector('.process-chapter');
          const cs = getComputedStyle(ch);
          const r = ch.getBoundingClientRect();
          const grid = document.querySelector('.process-grid');
          const gr = grid.getBoundingClientRect();
          return {
            bg: cs.getPropertyValue('--bg'), ink: cs.getPropertyValue('--ink'),
            bgColor: cs.backgroundColor, color: cs.color, display: cs.display,
            minHeight: cs.minHeight, height: Math.round(r.height),
            chapterRect: {t: Math.round(r.top), b: Math.round(r.bottom)},
            gridRect: {t: Math.round(gr.top), b: Math.round(gr.bottom)},
          };
        }''')
        print(data)
        await browser.close()

asyncio.run(main())

