import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

async def check(pg, w):
    await pg.set_viewport_size({"width": w, "height": 900})
    await pg.wait_for_timeout(150)
    return await pg.evaluate('''() => {
      const t = document.querySelector('.process-title');
      const h = document.querySelector('.thesis-headline');
      return {
        procTitle: getComputedStyle(t).fontSize,
        thesisHeadline: getComputedStyle(h).fontSize,
      };
    }''')

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        pg = await browser.new_page()
        await pg.goto(URL, wait_until="load", timeout=20000)
        await pg.wait_for_timeout(500)
        for w in [390, 768, 1024, 1280, 1440, 1920]:
            d = await check(pg, w)
            print(w, d)

        # card-mark via preview=back
        pg2 = await browser.new_page(viewport={"width":1440,"height":900})
        await pg2.goto(URL + "?preview=back", wait_until="load", timeout=20000)
        await pg2.wait_for_timeout(700)
        cm = await pg2.evaluate('''() => {
          const m = document.querySelector('.card-mark');
          const g = document.querySelector('.card-glyph');
          const s = document.querySelector('.card-services');
          const mr = m.getBoundingClientRect();
          const gr = g ? g.getBoundingClientRect() : null;
          const sr = s ? s.getBoundingClientRect() : null;
          function overlap(a,b){
            const ox = Math.max(0, Math.min(a.right,b.right)-Math.max(a.left,b.left));
            const oy = Math.max(0, Math.min(a.bottom,b.bottom)-Math.max(a.top,b.top));
            return ox>0 && oy>0;
          }
          return {
            fontSize: getComputedStyle(m).fontSize,
            markRect: {l:Math.round(mr.left),r:Math.round(mr.right),w:Math.round(mr.width)},
            collideGlyph: gr ? overlap(mr,gr) : null,
            collideServices: sr ? overlap(mr,sr) : null,
          };
        }''')
        print("card-mark @1440:", cm)
        await browser.close()

asyncio.run(main())

