            fontSize: getComputedStyle(m).fontSize,
            markRect: {l:Math.round(mr.left),r:Math.round(mr.right),w:Math.round(mr.width)},
            collideGlyph: gr ? overlap(mr,gr) : null,
            collideServices: sr ? overlap(mr,sr) : null,
          };
